import 'dart:convert';
void main() {
  const plain = '0d000721';
  final l1 = plain.split('').reversed.join();
  final xored = l1.codeUnits.map((c) => c ^ 0x5A).toList();
  final l3 = xored.map((b) => b.toRadixString(16).padLeft(2, '0')).join();
  final l4 = base64Encode(utf8.encode(l3));
  print(l4.split('').reversed.join());
}
